  "implementation": "def solve(case):
    nodes = case['nodes']
    core = case['core_distance']
    distances = case['distances']
    # Build edges: mutual reachability weight, canonical endpoints
    edges = []
    for a, b, d in distances:
        w = max(core[a], core[b], d)
        if a > b:
            a, b = b, a
        edges.append((w, a, b))
    # Sort by weight, then by a, then by b (all strings for tie-breaking)
    edges.sort(key=lambda x: (x[0], x[1], x[2]))
    # Union-Find with path compression and union by rank
    parent = {node: node for node in nodes}
    rank = {node: 0 for node in nodes}
    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x
    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            parent[rx] = ry
        elif rank[rx] > rank[ry]:
            parent[ry] = rx
        else:
            parent[ry] = rx
            rank[rx] += 1
        return True
    mst_edges = []
    total_weight = 0.0
    n = len(nodes)
    target = n - 1
    for w, a, b in edges:
        if len(mst_edges) == target:
            break
        if union(a, b):
            mst_edges.append([a, b, w])
            total_weight += w
    if len(mst_edges) != target:
        raise ValueError("Graph is disconnected, cannot compute MST")
    return {
        'mst_edges': mst_edges,
        'total_weight': total_weight
    }
